export function steps(kds: boolean) { return kds ? [3,5] : [3]; }
export async function send(value: number, callback: (n: number) => void) { callback(value); console.info("confirmed", value); }
export async function publish(values: number[]) { const results = await Promise.allSettled(values.map(v => send(v, n => console.info("confirmed", n)))); return results.flatMap((r,i) => { if (r.status === "fulfilled") return []; if (!values[i]) return []; return [r.reason]; }); }
